#pragma warning disable
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection.Metadata.Ecma335;
using System.Text;
using System.Threading.Tasks;
using UAssetAPI;
using UAssetAPI.ExportTypes;
using UAssetAPI.PropertyTypes.Objects;
using UAssetAPI.UnrealTypes;

namespace UFMT
{
    public record class UeVersion
    {
        public string FakeCIDBase64;
        public string CidJsonBase64;
        public string AssetRegistryBinBase64;
        public string BaseMeshBase64;
        public string BaseMeshSkeletonBase64;
        public string PythonScriptName;
        public string PhysicsImporterName;
        public string DefaultEngineIniBase64;
        public Action<string, string[]> FixRequiredFiles;
    }

    public class UeVersionsData
    {
        public static UeVersion Ue4_26 = new UeVersion()
        {
            CidJsonBase64 = @"",
            FakeCIDBase64 = @"",
            BaseMeshBase64 = @"",
            BaseMeshSkeletonBase64 = @"",
            AssetRegistryBinBase64 = @"",
            FixRequiredFiles = (string animationPath, string[] meshesPaths) =>
            {
                foreach (string meshPath in meshesPaths)
                {
                    string uassetPath = meshPath;
                    string uexpPath = Path.ChangeExtension(meshPath, ".uexp");
                    byte[] uasset = File.ReadAllBytes(uassetPath);
                    byte[] uexp = File.ReadAllBytes(uexpPath);

                    List<int> insertions = FindInsertions(uexp);

                    if (insertions.Count == 0)
                    {
                        SkinsPage.ConsoleWriteLineWarning("The cooked mesh may already be correct or was not cooked by UE 4.26.2.");
                        return;
                    }
                    //Fix .uexp 
                    byte[] fixedUexp = RemoveBytes(uexp, insertions);

                    //apply uexp's length changes in .uasset
                    int oldSerial = uexp.Length - 4;
                    int newSerial = fixedUexp.Length - 4;
                    int oldPkgSize = uasset.Length + oldSerial;
                    int newPkgSize = uasset.Length + newSerial;

                    byte[] fixedUasset = (byte[])uasset.Clone();
                    int c1 = PatchInt32All(fixedUasset, oldSerial, newSerial);
                    int c2 = PatchInt32All(fixedUasset, oldPkgSize, newPkgSize);

                    if (c1 == 0 || c2 == 0)
                    {
                        SkinsPage.ConsoleWriteLineWarning("\nWARNING: A header field was not found/patched. Output may be invalid.");
                    }
                    File.WriteAllBytes(uassetPath, fixedUasset);
                    File.WriteAllBytes(uexpPath, fixedUexp);
                }

                List<int> FindInsertions(byte[] uexp)
                {
                    var results = new List<int>();

                    int[] ones = { -17, -1, 0 };
                    int[] zeros = { -20, -19, -18, -16, -14, -10, -7, -6, -5, -4, -3, -2, 1, 2, 3, 6, 7, 8, 9, 10, 11, 13, 14, 15, 17 };

                    for (int i = 20; i < uexp.Length - 17; i++)
                    {
                        if (ones.Any(o => uexp[i + o] != 0x01)) continue;

                        if (zeros.Any(o => uexp[i + o] != 0x00)) continue;

                        results.Add(i);
                    }

                    return results;
                }

                byte[] RemoveBytes(byte[] data, List<int> offsets)
                {
                    var sorted = offsets.OrderBy(x => x).ToList();
                    var result = new List<byte>(data.Length - sorted.Count);
                    int prev = 0;
                    foreach (int off in sorted)
                    {
                        for (int i = prev; i < off; i++) result.Add(data[i]);
                        prev = off + 1;
                    }
                    for (int i = prev; i < data.Length; i++) result.Add(data[i]);
                    return result.ToArray();
                }

                int PatchInt32All(byte[] data, int oldValue, int newValue)
                {
                    byte b0 = (byte)(oldValue & 0xFF), b1 = (byte)((oldValue >> 8) & 0xFF),
                     b2 = (byte)((oldValue >> 16) & 0xFF), b3 = (byte)((oldValue >> 24) & 0xFF);
                    byte n0 = (byte)(newValue & 0xFF), n1 = (byte)((newValue >> 8) & 0xFF),
                     n2 = (byte)((newValue >> 16) & 0xFF), n3 = (byte)((newValue >> 24) & 0xFF);
                    int count = 0;
                    for (int i = 0; i <= data.Length - 4; i++)
                    {
                        if (data[i] == b0 && data[i + 1] == b1 && data[i + 2] == b2 && data[i + 3] == b3)
                        { data[i] = n0; data[i + 1] = n1; data[i + 2] = n2; data[i + 3] = n3; count++; }
                    }
                    return count;
                }

                uint ReadUInt32(byte[] data, int offset) =>
                 (uint)(data[offset] | (data[offset + 1] << 8) | (data[offset + 2] << 16) | (data[offset + 3] << 24));
            },
            PythonScriptName = "UE_4_25.py",
            PhysicsImporterName = "PhysicsImporter_UE4.26.zip"
        };
        public static UeVersion Ue4_25 = new UeVersion()
        {
            CidJsonBase64 = @"",
            FakeCIDBase64 = @"",
            BaseMeshBase64 = @"",
            BaseMeshSkeletonBase64 = @"",
            AssetRegistryBinBase64 = @"",
            PythonScriptName = "UE_4_25.py",
            PhysicsImporterName = "PhysicsImporter_UE4.25.zip",
            DefaultEngineIniBase64 = @"",
            FixRequiredFiles = (string animationPath, string[] meshesPaths) =>
            {
                if (!File.Exists(animationPath)) return;

                UAsset asset = new UAsset(animationPath, EngineVersion.VER_UE4_25);
                asset.SetEngineVersion(EngineVersion.VER_UE4_26);

                Import packImport = new Import(
                    "/Script/CoreUObject",
                    "Package",
                    new FPackageIndex(0),
                    "/Engine/Animation/DefaultAnimCurveCompressionSettings",
                    false,
                    asset
                );
                asset.Imports.Add(packImport);
                int packImportIndex = asset.Imports.Count;

                Import objImport = new Import(
                    "/Script/Engine",
                    "AnimCurveCompressionSettings",
                    new FPackageIndex(-packImportIndex),
                    "DefaultAnimCurveCompressionSettings",
                    false,
                    asset
                );
                asset.Imports.Add(objImport);
                int objImportIndex = asset.Imports.Count;

                var normalExport = (NormalExport)asset.Exports[0];
                ObjectPropertyData curveProp = new ObjectPropertyData(new FName(asset, "CurveCompressionSettings"));
                curveProp.Value = new FPackageIndex(-objImportIndex);
                normalExport.Data.Add(curveProp);

                asset.Write(animationPath);
                Console.WriteLine("Fixed!");
            }
        };
        public static UeVersion Ue4_26_Modded = Ue4_25 with
        {
            FakeCIDBase64 = @"",
            PythonScriptName = "UE_4_26_Modded.py",
            FixRequiredFiles = (string animationPath, string[] meshesPaths) => { } //Nothing to fix 
        };
        public static UeVersion Ue4_22 = new()
        {
            FakeCIDBase64 = @"",
            CidJsonBase64 = @"",
            AssetRegistryBinBase64 = @"",
            BaseMeshBase64 = @"",
            BaseMeshSkeletonBase64 = @"",
            PythonScriptName = "UE_4_22.py",
            PhysicsImporterName = "PhysicsImporter_UE4.22.zip",
            DefaultEngineIniBase64 = @"",
            FixRequiredFiles = (string animationPath, string[] meshesPaths) =>
            {
                if (!File.Exists(animationPath)) return;

                const int UEXP_INSERTION_OFFSET = 13312;
                const int BYTES_TO_INSERT = 4;

                string uassetPath = animationPath;
                string uexpPath = Path.ChangeExtension(uassetPath, ".uexp");

                byte[] uasset = File.ReadAllBytes(uassetPath);
                byte[] uexp = File.ReadAllBytes(uexpPath);

                if (uexp.Length <= UEXP_INSERTION_OFFSET + BYTES_TO_INSERT)
                {
                    SkinsPage.ConsoleWriteLineWarning($".uexp is too small ({uexp.Length} bytes) to contain the expected insertion point at offset {UEXP_INSERTION_OFFSET}.");
                    return;
                }

                if (!ParseUAssetHeader(uasset,
                        out int serialSizeOffset,
                        out int assetRegOffset_FieldOffset,
                        out int totalHeaderSize))
                {
                    SkinsPage.ConsoleWriteLineWarning("Could not parse .uasset header.");
                    return;
                }

                long serialSizeOld = ReadInt64(uasset, serialSizeOffset);
                uint assetRegOffOld = ReadUInt32(uasset, assetRegOffset_FieldOffset);
                int assetRegInUexp = (int)assetRegOffOld - totalHeaderSize;

                if (UEXP_INSERTION_OFFSET >= assetRegInUexp) return;

                byte[] uexpPatched = InsertZeroBytes(uexp, UEXP_INSERTION_OFFSET, BYTES_TO_INSERT);
                byte[] uassetPatched = (byte[])uasset.Clone();

                long serialSizeNew = serialSizeOld + BYTES_TO_INSERT;
                WriteInt64(uassetPatched, serialSizeOffset, serialSizeNew);

                uint assetRegOffNew = assetRegOffOld + (uint)BYTES_TO_INSERT;
                WriteUInt32(uassetPatched, assetRegOffset_FieldOffset, assetRegOffNew);
                string outUasset = Path.Combine(
                    Path.GetDirectoryName(uassetPath) ?? ".",
                    Path.GetFileNameWithoutExtension(uassetPath) + ".uasset");
                string outUexp = Path.ChangeExtension(outUasset, ".uexp");

                File.WriteAllBytes(outUasset, uassetPatched);
                File.WriteAllBytes(outUexp, uexpPatched);
                return;

                byte[] InsertZeroBytes(byte[] data, int afterOffset, int count)
                {
                    int insertPos = afterOffset + 1;
                    byte[] result = new byte[data.Length + count];
                    Buffer.BlockCopy(data, 0, result, 0, insertPos);
                    Buffer.BlockCopy(data, insertPos, result, insertPos + count, data.Length - insertPos);
                    return result;
                }

                bool ParseUAssetHeader(byte[] data,
                    out int serialSizeOffset,
                    out int assetRegDataOffset_FieldOffset,
                    out int totalHeaderSize)
                {
                    serialSizeOffset = -1;
                    assetRegDataOffset_FieldOffset = -1;
                    totalHeaderSize = -1;

                    if (data.Length < 64) return false;

                    uint magic = ReadUInt32(data, 0);
                    if (magic != 0x9E2A83C1) return false;

                    int off = 4;
                    int legacyFileVersion = ReadInt32(data, off); off += 4;
                    if (legacyFileVersion >= 0) return false;

                    if (legacyFileVersion != -4) off += 4;
                    off += 8;

                    int customCount = ReadInt32(data, off); off += 4;
                    if (customCount < 0 || customCount > 1000) return false;
                    off += customCount * 20;

                    totalHeaderSize = ReadInt32(data, off); off += 4;

                    int folderLen = ReadInt32(data, off); off += 4;
                    if (folderLen < 0) off += (-folderLen) * 2;
                    else off += folderLen;

                    off += 4;
                    off += 8;
                    off += 8;

                    int exportCount = ReadInt32(data, off); off += 4;
                    int exportOffset = ReadInt32(data, off); off += 4;

                    off += 8;
                    off += 4;
                    off += 8;
                    off += 4;
                    off += 4;
                    off += 16;

                    int genCount = ReadInt32(data, off); off += 4;
                    if (genCount < 0 || genCount > 100) return false;
                    off += genCount * 8;

                    off += 6;
                    off += 4;
                    int branchLen = ReadInt32(data, off); off += 4;
                    off += Math.Abs(branchLen) * (branchLen < 0 ? 2 : 1);

                    off += 6;
                    off += 4;
                    int branchLen2 = ReadInt32(data, off); off += 4;
                    off += Math.Abs(branchLen2) * (branchLen2 < 0 ? 2 : 1);

                    off += 4;

                    int compChunks = ReadInt32(data, off); off += 4;
                    if (compChunks != 0) return false;

                    off += 4;
                    int addPkg = ReadInt32(data, off); off += 4;
                    off += 4;

                    assetRegDataOffset_FieldOffset = off;
                    off += 4;
                    off += 8;
                    off += 4;

                    int chunkCount = ReadInt32(data, off); off += 4;
                    off += chunkCount * 4;
                    off += 8;

                    if (exportCount < 1 || exportOffset < 0 || exportOffset + 0x60 > data.Length)
                        return false;

                    int eoff = exportOffset;
                    eoff += 7 * 4;
                    serialSizeOffset = eoff;

                    return true;
                }

                int ReadInt32(byte[] d, int o) => d[o] | (d[o + 1] << 8) | (d[o + 2] << 16) | (d[o + 3] << 24);
                uint ReadUInt32(byte[] d, int o) => (uint)(d[o] | (d[o + 1] << 8) | (d[o + 2] << 16) | (d[o + 3] << 24));
                long ReadInt64(byte[] d, int o) => (long)ReadUInt32(d, o) | ((long)ReadUInt32(d, o + 4) << 32);

                void WriteInt32(byte[] d, int o, int v)
                {
                    d[o] = (byte)(v & 0xFF);
                    d[o + 1] = (byte)((v >> 8) & 0xFF);
                    d[o + 2] = (byte)((v >> 16) & 0xFF);
                    d[o + 3] = (byte)((v >> 24) & 0xFF);
                }
                void WriteUInt32(byte[] d, int o, uint v)
                {
                    d[o] = (byte)(v & 0xFF);
                    d[o + 1] = (byte)((v >> 8) & 0xFF);
                    d[o + 2] = (byte)((v >> 16) & 0xFF);
                    d[o + 3] = (byte)((v >> 24) & 0xFF);
                }
                void WriteInt64(byte[] d, int o, long v)
                {
                    WriteUInt32(d, o, (uint)(v & 0xFFFFFFFF));
                    WriteUInt32(d, o + 4, (uint)((v >> 32) & 0xFFFFFFFF));
                }
            }
        };
        public static Dictionary<string, UeVersion> UeVersions = new () { { "UE_4.25", Ue4_25 } , { "UE_4.26", Ue4_26 }, 
            { "UE_4.26_FnGameProj", Ue4_26_Modded }, { "UE_4.22", Ue4_22 } };
    }
}
